@SpringBootTest
class ConcurrencyTest {

    @Autowired
    private SegmentService segmentService;
    @Autowired
    private AssignmentService assignmentService;
    @Autowired
    private JdbcTemplate jdbc;
    @Autowired
    private MutableClock clock;

    private ExecutorService executor;

